#include "security/event_queue.h"
#include "util/device_identity.h"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <thread>
#include <vector>
#include <miniz.h>
#include <nlohmann/json.hpp>
namespace fs=std::filesystem; using namespace chudware::security;
static int failures=0; static void check(bool v,const char*m){if(!v){++failures;std::cerr<<"FAIL: "<<m<<'\n';}}
static fs::path fresh(const char*n){auto p=fs::temp_directory_path()/(std::string("cw-sec-")+n+"-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(p);chudware::device_identity::ensureForAuthorization(p.string());return p;}
int main(){const auto now=1800000000LL;
 {auto p=fresh("concurrent");std::vector<std::thread> t;for(int n=0;n<8;n++)t.emplace_back([&,n]{EventQueue q(p.string());for(int i=0;i<50;i++)check(q.append({"heartbeat",now+n*50+i,0}),"concurrent append");});for(auto&x:t)x.join();EventQueue q(p.string());check(q.size()==400,"all concurrent rows retained");fs::remove_all(p);}
 {auto p=fresh("evict");EventQueue q(p.string());for(int i=0;i<1000;i++)check(q.append({"heartbeat",now+i,0}),"fill zero queue");check(q.append({"manifest_signature_invalid",now+1001,100}),"nonzero evicts zero");for(int i=0;i<999;i++)check(q.append({"protected_file_hash_mismatch",now+2000+i,80}),"replace zeros");check(!q.append({"debugger_attached",now+4000,35}),"full evidence queue fails closed");check(q.size()==1000,"nonzero evidence preserved");fs::remove_all(p);}
 {auto p=fresh("ack");EventQueue q(p.string());q.append({"debugger_attached",now,35});q.append({"heartbeat",now+1,0});auto a=q.prepareBatch("00000000-0000-0000-0000-000000000001","p1","1.2.3","linux",now);auto b=q.prepareBatch("00000000-0000-0000-0000-000000000001","p1","1.2.3","linux",now+1);check(a&&a.batchId==b.batchId&&a.sequence==b.sequence&&a.body==b.body,"retry is byte stable");check(a.batchId.size()==36&&a.batchId[8]=='-'&&a.batchId[13]=='-'&&a.batchId[18]=='-'&&a.batchId[23]=='-',"batch id is UUID");auto wire=nlohmann::json::parse(a.body);check(wire["events"][0]["occurred_at"]=="2027-01-15T08:00:00Z","event timestamp is RFC3339 UTC");check(q.accept(a.batchId,a.sequence-1),"partial ack accepted");check(q.size()==2,"partial ack removes nothing");check(q.accept(a.batchId,a.sequence),"full ack accepted");check(q.size()==0&&q.acceptedThrough("00000000-0000-0000-0000-000000000001")==a.sequence,"accepted rows removed");fs::remove_all(p);}
 {auto p=fresh("rebind");EventQueue q(p.string());const std::string s1="00000000-0000-0000-0000-000000000001",s2="00000000-0000-0000-0000-000000000002";q.append({"debugger_attached",now,35});auto a=q.prepareBatch(s1,"p1","1.2.3","linux",now);check(a&&q.accept(a.batchId,a.sequence)&&q.acceptedThrough(s1)==a.sequence,"first subject acknowledged");q.append({"debugger_attached",now+1,35});auto b=q.prepareBatch(s1,"p1","1.2.3","linux",now+1);auto c=q.prepareBatch(s2,"p1","1.2.3","linux",now+2);check(b&&c&&c.sequence==1&&c.batchId!=b.batchId,"new device subject restarts the sequence instead of replaying the old pending batch");check(q.acceptedThrough(s2)==0,"new subject starts unacknowledged");check(c.body.find(s2)!=std::string::npos&&c.eventCount==1,"unacknowledged evidence moves to the new subject");fs::remove_all(p);}
 {std::string plain(4096,'x'),gz;check(gzipSecurityPayload(plain,gz)&&gz.size()<plain.size()&&static_cast<unsigned char>(gz[0])==0x1f&&static_cast<unsigned char>(gz[1])==0x8b,"gzip encoding and bound");mz_stream s{};check(mz_inflateInit2(&s,-MZ_DEFAULT_WINDOW_BITS)==MZ_OK,"gzip raw inflater init");std::string out(plain.size(),'\0');s.next_in=reinterpret_cast<const unsigned char*>(gz.data()+10);s.avail_in=static_cast<unsigned>(gz.size()-18);s.next_out=reinterpret_cast<unsigned char*>(out.data());s.avail_out=static_cast<unsigned>(out.size());check(mz_inflate(&s,MZ_FINISH)==MZ_STREAM_END&&out==plain,"gzip deflate roundtrip");mz_inflateEnd(&s);}
 {auto p=fresh("corrupt");EventQueue q(p.string());q.append({"manifest_signature_invalid",now,100});std::ofstream(p/"security/events.v1",std::ios::app)<<"not-json\n";check(q.append({"heartbeat",now+1,0}),"corrupt tail recovered");check(q.size()==2,"parseable nonzero retained");check(fs::exists(p/"security/events.v1.corrupt"),"corrupt source quarantined");fs::remove_all(p);}
 check(!approvedSecurityReason("filename")&&!approvedSecurityReason("command_line"),"sensitive fields rejected");if(failures)return 1;std::cout<<"security event queue: PASS\n";return 0;}
